# Nur in EN-Woerterbuechern ersetzen: kurze Texte, die es auch auf Deutsch gibt, waeren sonst gefaehrdet.
NUR_IN_EN = {"Privacy", "Register", "Subscribe", "Granted", "Snapshot", "cancelled", "payment due"}


def anwenden(html):
    """Ersetzt die EN-Texte; liefert (html, liste der tatsaechlich ersetzten Paare)."""
    import re
    erledigt = []
    for alt, neu in ERSETZEN:
        assert "'" not in neu and '"' not in neu, neu
        n = 0
        for q in ("'", '"'):
            muster = q + alt + q
            if alt in NUR_IN_EN:
                # nur innerhalb von en-Woerterbuechern: Schluessel:'Text'
                html, k = re.subn(r"(?<=[a-zA-Z_0-9]:)" + re.escape(muster), q + neu + q, html)
            else:
                k = html.count(muster)
                html = html.replace(muster, q + neu + q)
            n += k
        if n == 0:
            raise SystemExit("EN-Text nicht gefunden: " + alt[:80])
        erledigt.append((alt, neu))
    return html, erledigt
